def can_open_bomb_grotto(bundle) -> bool:
    return blast_or_smash(bundle) & (has_item(bundle, Items.RG_STONE_OF_AGONY) | can_do_trick(bundle, Tricks.RT_GROTTOS_WITHOUT_AGONY))

def can_open_overworld_door(bundle, key: Items) -> bool:
    return True_(options=[OptionFilter(RSK_LOCK_OVERWORLD_DOORS, False)]) | has_item(bundle, Items.RG_SKELETON_KEY) | has_item(bundle, key)

def can_open_storms_grotto(bundle) -> bool:
    return can_use(bundle, Items.RG_SONG_OF_STORMS) & (has_item(bundle, Items.RG_STONE_OF_AGONY) | can_do_trick(bundle, Tricks.RT_GROTTOS_WITHOUT_AGONY))

def can_open_underwater_chest(bundle) -> bool:
    return can_do_trick(bundle, Tricks.RT_OPEN_UNDERWATER_CHEST) & can_use(bundle, Items.RG_IRON_BOOTS) & can_use(bundle, Items.RG_HOOKSHOT) & has_item(bundle, Items.RG_OPEN_CHEST)

