def can_reflect_nuts(bundle) -> bool:
    return can_use(bundle, Items.RG_DEKU_SHIELD) | is_adult(bundle) & has_item(bundle, Items.RG_HYLIAN_SHIELD)

def can_shield(bundle) -> bool:
    return can_use(bundle, Items.RG_MIRROR_SHIELD) | has_item(bundle, Items.RG_HYLIAN_SHIELD) | can_use(bundle, Items.RG_DEKU_SHIELD)

def can_spawn_soil_skull(bundle, bean: Items) -> bool:
    return is_child(bundle) & can_use(bundle, Items.RG_BOTTLE_WITH_BUGS) & has_item(bundle, bean)

def can_standing_shield(bundle) -> bool:
    return can_use(bundle, Items.RG_MIRROR_SHIELD) | is_adult(bundle) & has_item(bundle, Items.RG_HYLIAN_SHIELD) | can_use(bundle, Items.RG_DEKU_SHIELD)

def can_stun_deku(bundle) -> bool:
    return can_attack(bundle) | can_use(bundle, Items.RG_NUTS) | can_reflect_nuts(bundle)

def can_use_projectile(bundle) -> bool:
    return has_explosives(bundle) | can_use(bundle, Items.RG_FAIRY_BOW) | can_use(bundle, Items.RG_HOOKSHOT) | can_use(bundle, Items.RG_FAIRY_SLINGSHOT) | can_use(bundle, Items.RG_BOOMERANG)

def can_use_sword(bundle) -> bool:
    return can_use(bundle, Items.RG_KOKIRI_SWORD) | can_use(bundle, Items.RG_MASTER_SWORD) | can_use(bundle, Items.RG_BIGGORON_SWORD)

def could_mq_spirit_4_key_west_hand(bundle) -> bool:
    return can_avoid(bundle, Enemies.RE_BEAMOS, True, 4) & can_use(bundle, Items.RG_SONG_OF_TIME) & (has_item(bundle, Items.RG_MASTER_SWORD) | has_item(bundle, Items.RG_BIGGORON_SWORD) | has_item(bundle, Items.RG_MEGATON_HAMMER)) & (has_item(bundle, Items.RG_POWER_BRACELET) | sunlight_arrows(bundle)) & (can_do_trick(bundle, Tricks.RT_LENS_SPIRIT_MQ) | can_use(bundle, Items.RG_LENS_OF_TRUTH)) & has_item(bundle, Items.RG_LONGSHOT)

def dmc_pad_to_pots(bundle) -> bool:
    return can_use(bundle, Items.RG_HOVER_BOOTS) & (is_adult(bundle) | has_item(bundle, Items.RG_CLIMB)) | can_use(bundle, Items.RG_HOOKSHOT)

def dmc_pots_to_pad(bundle) -> bool:
    return can_use(bundle, Items.RG_HOVER_BOOTS) | can_use(bundle, Items.RG_HOOKSHOT) | is_adult(bundle) & can_shield(bundle) & can_do_trick(bundle, Tricks.RT_DMC_BOLERO_JUMP) & can_use(bundle, Items.RG_POWER_BRACELET)

def dmc_upper_to_pots(bundle) -> bool:
    return can_use(bundle, Items.RG_HOVER_BOOTS) | is_adult(bundle) & (has_item(bundle, Events.LOGIC_DMC_BOULDER) | can_do_trick(bundle, Tricks.RT_DMC_BOULDER_SKIP))

def has_boss_soul(bundle, item: Items) -> bool:
    return True_(options=[OptionFilter(RSK_SHUFFLE_BOSS_SOULS, False)]) | rls_match_rule((lambda item=item: item == Items.RG_GOHMA_SOUL or item == Items.RG_KING_DODONGO_SOUL or item == Items.RG_BARINADE_SOUL or item == Items.RG_PHANTOM_GANON_SOUL or item == Items.RG_VOLVAGIA_SOUL or item == Items.RG_MORPHA_SOUL or item == Items.RG_BONGO_BONGO_SOUL or item == Items.RG_TWINROVA_SOUL), (lambda: has_item(bundle, item)), False, (lambda item=item: item == Items.RG_GANON_SOUL), (lambda: True_(options=[OptionFilter(RSK_SHUFFLE_BOSS_SOULS, RandomizerSettingKey.RO_BOSS_SOULS_ON_PLUS_GANON, "ne")]) | has_item(bundle, Items.RG_GANON_SOUL)), False, (lambda: True), (lambda: False_()), False)

def has_bottle(bundle) -> bool:
    return has_bottle_count(bundle, 1)

def has_explosives(bundle) -> bool:
    return can_use(bundle, Items.RG_BOMB_BAG) | can_use(bundle, Items.RG_BOMBCHU_5)

def has_fire_source(bundle) -> bool:
    return can_use(bundle, Items.RG_DINS_FIRE) | can_use(bundle, Items.RG_FIRE_ARROWS)

def has_fire_source_with_torch(bundle) -> bool:
    return has_fire_source(bundle) | can_use(bundle, Items.RG_STICKS)

def has_projectile(bundle, age: HasProjectileAge) -> bool:
    return has_explosives(bundle) | (can_use(bundle, Items.RG_FAIRY_SLINGSHOT) | can_use(bundle, Items.RG_BOOMERANG) if age == HasProjectileAge.Child else False_()) | (can_use(bundle, Items.RG_HOOKSHOT) | can_use(bundle, Items.RG_FAIRY_BOW) if age == HasProjectileAge.Adult else False_()) | (can_use(bundle, Items.RG_FAIRY_SLINGSHOT) | can_use(bundle, Items.RG_BOOMERANG) if age == HasProjectileAge.Both else False_()) & (can_use(bundle, Items.RG_HOOKSHOT) | can_use(bundle, Items.RG_FAIRY_BOW)) | (can_use(bundle, Items.RG_FAIRY_SLINGSHOT) | can_use(bundle, Items.RG_BOOMERANG) | can_use(bundle, Items.RG_HOOKSHOT) | can_use(bundle, Items.RG_FAIRY_BOW) if age == HasProjectileAge.Either else False_())

def hookshot_or_boomerang(bundle) -> bool:
    return can_use(bundle, Items.RG_HOOKSHOT) | can_use(bundle, Items.RG_BOOMERANG)

def is_fire_loop_locked(bundle) -> bool:
    return True_(options=[OptionFilter(RSK_KEYSANITY, RandomizerSettingKey.RO_DUNGEON_ITEM_LOC_ANYWHERE)]) | True_(options=[OptionFilter(RSK_KEYSANITY, RandomizerSettingKey.RO_DUNGEON_ITEM_LOC_OVERWORLD)]) | True_(options=[OptionFilter(RSK_KEYSANITY, RandomizerSettingKey.RO_DUNGEON_ITEM_LOC_ANY_DUNGEON)])

def is_reverse_access_possible(bundle) -> bool:
    return True_(options=[OptionFilter(RSK_SHUFFLE_BOSS_ENTRANCES, RandomizerSettingKey.RO_BOSS_ROOM_ENTRANCE_SHUFFLE_OFF, "ne")]) & (True_(options=[OptionFilter(RSK_DECOUPLED_ENTRANCES, True)]) & True_(options=[OptionFilter(RSK_SHUFFLE_BOSS_ENTRANCES, RandomizerSettingKey.RO_BOSS_ROOM_ENTRANCE_SHUFFLE_FULL)]) | True_(options=[OptionFilter(RSK_MIX_BOSS_ENTRANCES, True)]) & (True_(options=[OptionFilter(RSK_MIX_OVERWORLD_ENTRANCES, True)]) | True_(options=[OptionFilter(RSK_MIX_INTERIOR_ENTRANCES, True)])))

